          throw ApplicationFailure.newNonRetryableFailure(e.getMessage(), "PaymentDeclined", e.toDetail());
        } catch (Exception e) {
          throw Activity.wrap(e); // uniform fallback: type = class name, retryable
        }
      }
    };
